// ── Random User-Agent ──
const UAS = [
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Safari/605.1.15',
  'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:125.0) Gecko/20100101 Firefox/125.0',
  'Mozilla/5.0 (iPhone; CPU iPhone OS 17_4 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.4 Mobile/15E148 Safari/604.1'
];
const ua = UAS[Math.floor(Math.random() * UAS.length)];
return [{ json: { userAgent: ua } }];

// ── Mamikos: Parse + Filter + Deduplicate ──
const staticData = $getWorkflowStaticData('global');
if (!staticData.sentIds) staticData.sentIds = {};

// TTL cleanup — hapus entry > 24 jam
const now = Date.now();
for (const id in staticData.sentIds) {
  if (now - staticData.sentIds[id] > 86400000) delete staticData.sentIds[id];
}

const raw = $input.first().json;
// Mamikos bisa return 'data', 'rooms', 'results', atau langsung array
const rooms = raw.data?.rooms || raw.data?.results || raw.rooms || raw.results || raw.data || [];
if (!Array.isArray(rooms)) {
  console.log('Mamikos: unexpected response shape', JSON.stringify(raw).slice(0, 200));
  return [];
}

const output = [];

for (const room of rooms) {
  // ── Price filter Rp 300k–800k ──
  const price = parseInt(room.price_per_month || room.price?.amount || room.price || 0);
  if (!price || price < 300000 || price > 800000) continue;

  // ── Location / Surabaya keyword filter ──
  const locText = [
    room.address, room.location, room.area_name,
    room.city, room.district, room.name, room.title
  ].filter(Boolean).join(' ').toLowerCase();
  const isSurabaya = locText.includes('surabaya') || locText.includes('sby') ||
                     locText.includes('jawa timur') || locText.includes('jatim');
  if (!isSurabaya) continue;

  // ── Image filter — minimal 1 foto ──
  const rawPhotos = room.photos || room.images || room.pictures || [];
  const images = rawPhotos
    .map(p => (typeof p === 'string' ? p : p?.url || p?.photo_url || p?.src || ''))
    .filter(u => u && u.startsWith('http'))
    .slice(0, 5);
  if (images.length === 0) continue;

  // ── Deduplication via static data ──
  const uid = 'mamikos_' + (room.id || room.slug || room.uuid ||
    Buffer.from(room.name + price).toString('base64').slice(0, 12));
  if (staticData.sentIds[uid]) continue;
  staticData.sentIds[uid] = now;

  // ── Build payload ──
  const slug = room.slug || room.id || uid.replace('mamikos_', '');
  output.push({
    json: {
      source: 'mamikos',
      title: room.name || room.title || 'Kos Surabaya',
      price,
      location: [
        room.address, room.district, room.area_name, room.city
      ].filter(Boolean).join(', ') || 'Surabaya',
      url: room.url || `https://mamikos.com/kamar/${slug}`,
      description: (room.description || room.facilities_text || '').slice(0, 500),
      images,
      scraped_at: new Date().toISOString()
    }
  });
}

console.log(`Mamikos: ${output.length} listings passed filters`);
return output;
